  const result = exportCsv(invoices);
  // due = 10000 - 4000 = 6000 cents = 60.00
  const lines = result.split('\n');
  const fields = lines[1].split(',');
  assert.equal(fields[fields.length - 1], '60.00');
});

test('exportCsv: handles multiple invoices in order', () => {
  const invoices = [
    {
      number: '001',
      customerId: 'INVALID_ID',
      issueDate: '2025-01-01',
      dueDate: '2025-01-31',
      status: 'draft',
