    {
      number: '001',
      customerId: 'INVALID_ID',
      issueDate: '2025-01-01',
      dueDate: '2025-01-31',
      status: 'draft',
      lines: [],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  assert.equal(lines.length, 3); // header, one invoice, final empty line
});

test('exportCsv: proper CSV line structure', () => {
  const invoices = [
    {
      number: '001',
      customerId: 'INVALID_ID',
      issueDate: '2025-01-01',
      dueDate: '2025-01-31',
      status: 'draft',
      lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  // Split by comma and count fields (accounting for quoted fields)
  const fields = lines[1].split(',').length;
  // Should have 10 fields for the columns
  assert.equal(fields, 10);
});

test('exportCsv: handles multiple lines on same invoice', () => {
  const invoices = [
    {
      number: '001',
      customerId: 'INVALID_ID',
      issueDate: '2025-01-01',
      dueDate: '2025-01-31',
      status: 'draft',
      lines: [
        { qty: 2, unitPrice: 5000, discountPercent: 0, vatRate: 0 },
        { qty: 3, unitPrice: 3000, discountPercent: 0, vatRate: 0 },
      ],
    },
  ];
  const result = exportCsv(invoices);
  // subtotal = 2*5000 + 3*3000 = 10000 + 9000 = 19000 cents = 190.00
  assert.ok(result.includes('190.00'));
});

test('exportCsv: handles complex invoice with discount and VAT', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'INVALID_ID',
      issueDate: '2025-01-15',
      dueDate: '2025-02-15',
      status: 'issued',
      lines: [
        { qty: 1, unitPrice: 10000, discountPercent: 20, vatRate: 21 },
      ],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  // subtotal = 10000, discount = 2000, vat = (10000-2000)*0.21 = 1680, total = 10000-2000+1680 = 9680
  assert.ok(lines[1].includes('INV-001'));
  assert.ok(lines[1].includes('2025-01-15'));
  assert.ok(lines[1].includes('2025-02-15'));
  assert.ok(lines[1].includes('issued'));
});

